package com.devpro.pizzatime.feature.customer.orderdetail

import android.os.Bundle
import android.view.LayoutInflater
import android.view.View
import android.view.ViewGroup
import android.widget.Toast
import androidx.core.view.isVisible
import androidx.fragment.app.Fragment
import com.devpro.pizzatime.R
import com.devpro.pizzatime.databinding.FragmentCustomerOrderDetailBinding
import com.devpro.pizzatime.databinding.ItemCustomerOrderDetailLineBinding
import java.util.Locale

class CustomerOrderDetailFragment : Fragment() {

    private var _binding: FragmentCustomerOrderDetailBinding? = null
    private val binding: FragmentCustomerOrderDetailBinding
        get() = checkNotNull(_binding) {
            "FragmentCustomerOrderDetailBinding is only valid between onCreateView and onDestroyView."
        }

    private val orderDetail: CustomerOrderDetailUiModel by lazy {
        FakeCustomerOrderDetailData.getOrderDetail(
            orderId = arguments?.getString(ARG_ORDER_ID) ?: DEFAULT_ORDER_ID,
        )
    }

    override fun onCreateView(
        inflater: LayoutInflater,
        container: ViewGroup?,
        savedInstanceState: Bundle?,
    ): View {
        _binding = FragmentCustomerOrderDetailBinding.inflate(inflater, container, false)
        return binding.root
    }

    override fun onViewCreated(view: View, savedInstanceState: Bundle?) {
        bindOrderDetail()
        setupActions()

    }

    private fun bindOrderDetail() = with(binding) {
        tvStatus.text = orderDetail.statusLabel
        tvOrderId.text = getString(R.string.customer_order_detail_order_id, orderDetail.orderId)
        tvOrderTime.text = orderDetail.orderTime
        ivHeroImage.setImageResource(orderDetail.heroImageRes)
        tvHeroMessage.text = orderDetail.heroMessage

        bindItems()
        bindBill()
        bindAddress()
    }

    private fun bindItems() = with(binding.orderItemsContainer) {
        removeAllViews()

        orderDetail.items.forEach { item ->
            val itemBinding = ItemCustomerOrderDetailLineBinding.inflate(layoutInflater, this, false)

            itemBinding.tvItemName.text = getString(
                R.string.customer_order_detail_item_name,
                item.quantity,
                item.name,
            )
            itemBinding.tvItemDescription.text = item.description
            itemBinding.tvItemPrice.text = formatPrice(item.price)

            if (item.imageRes != null) {
                itemBinding.ivItemImage.setImageResource(item.imageRes)
                itemBinding.tvItemPlaceholder.isVisible = false
            } else {
                itemBinding.ivItemImage.setImageResource(0)
                itemBinding.tvItemPlaceholder.isVisible = true
            }

            addView(itemBinding.root)
        }
    }

    private fun bindBill() = with(binding) {
        tvSubtotalValue.text = formatPrice(orderDetail.bill.subtotal)
        tvDeliveryFeeValue.text = formatPrice(orderDetail.bill.deliveryFee)
        tvTaxesValue.text = formatPrice(orderDetail.bill.taxes)
        tvDiscountLabel.text = orderDetail.bill.discountLabel
        tvDiscountValue.text = formatSignedPrice(orderDetail.bill.discount)
        tvTotalAmount.text = formatPrice(orderDetail.bill.total)
    }

    private fun bindAddress() = with(binding) {
        tvDeliveredTo.text = orderDetail.deliveryAddressTitle
        tvAddressLine1.text = orderDetail.deliveryAddressLine1
        tvAddressLine2.text = orderDetail.deliveryAddressLine2
    }

    private fun setupActions() = with(binding) {
        btnReorder.setOnClickListener {
            Toast.makeText(
                requireContext(),
                getString(R.string.customer_order_detail_reorder_toast),
                Toast.LENGTH_SHORT,
            ).show()
        }

        btnSupport.setOnClickListener {
            Toast.makeText(
                requireContext(),
                getString(R.string.customer_order_detail_support_toast),
                Toast.LENGTH_SHORT,
            ).show()
        }
    }

    private fun formatPrice(value: Double): String {
        return String.format(Locale.US, "$%.2f", value)
    }

    private fun formatSignedPrice(value: Double): String {
        return if (value < 0) {
            String.format(Locale.US, "-$%.2f", kotlin.math.abs(value))
        } else {
            String.format(Locale.US, "$%.2f", value)
        }
    }

    override fun onDestroyView() {
        _binding = null
        super.onDestroyView()
    }

    companion object {
        private const val ARG_ORDER_ID = "arg_order_id"
        private const val DEFAULT_ORDER_ID = "PT-9821"

        fun newInstance(orderId: String): CustomerOrderDetailFragment {
            return CustomerOrderDetailFragment().apply {
                arguments = Bundle().apply {
                    putString(ARG_ORDER_ID, orderId)
                }
            }
        }
    }
}

package com.devpro.pizzatime.feature.customer.orderdetail

import android.os.Bundle
import android.view.LayoutInflater
import android.view.View
import android.view.ViewGroup
import android.widget.Toast
import androidx.core.view.isVisible
import androidx.fragment.app.Fragment
import com.devpro.pizzatime.R
import com.devpro.pizzatime.databinding.FragmentCustomerOrderDetailBinding
import com.devpro.pizzatime.databinding.ItemCustomerOrderDetailLineBinding
import com.devpro.pizzatime.feature.customer.orderhistory.CustomerOrderFirestoreRepository
import java.util.Locale

class CustomerOrderDetailFragment : Fragment() {

    private var _binding: FragmentCustomerOrderDetailBinding? = null
    private val binding: FragmentCustomerOrderDetailBinding
        get() = checkNotNull(_binding) {
            "FragmentCustomerOrderDetailBinding is only valid between onCreateView and onDestroyView."
        }

    override fun onCreateView(
        inflater: LayoutInflater,
        container: ViewGroup?,
        savedInstanceState: Bundle?,
    ): View {
        _binding = FragmentCustomerOrderDetailBinding.inflate(inflater, container, false)
        return binding.root
    }

    override fun onViewCreated(view: View, savedInstanceState: Bundle?) {
        setupActions()
        val orderId = arguments?.getString(ARG_ORDER_ID).orEmpty()
        loadOrder(orderId)
    }

    private fun loadOrder(orderId: String) {
        if (isFirestoreOrderId(orderId)) {
            CustomerOrderFirestoreRepository.loadOrderDetail(orderId) { result ->
                if (!isAdded) return@loadOrderDetail
                val detail = result.getOrElse {
                    FakeCustomerOrderDetailData.getOrderDetail(orderId.ifBlank { DEFAULT_ORDER_ID })
                }
                bindOrderDetail(detail)
            }
        } else {
            bindOrderDetail(
                FakeCustomerOrderDetailData.getOrderDetail(orderId.ifBlank { DEFAULT_ORDER_ID })
            )
        }
    }

    private fun isFirestoreOrderId(orderId: String): Boolean =
        orderId.isNotBlank() && !orderId.startsWith("#") && orderId.length > 8

    private fun bindOrderDetail(detail: CustomerOrderDetailUiModel) = with(binding) {
        tvStatus.text = detail.statusLabel
        tvOrderId.text = getString(R.string.customer_order_detail_order_id, detail.orderId)
        tvOrderTime.text = detail.orderTime
        ivHeroImage.setImageResource(detail.heroImageRes)
        tvHeroMessage.text = detail.heroMessage

        bindItems(detail.items)
        bindBill(detail.bill)
        bindAddress(detail)
    }

    private fun bindItems(items: List<CustomerOrderItemUiModel>) = with(binding.orderItemsContainer) {
        removeAllViews()

        items.forEach { item ->
            val itemBinding = ItemCustomerOrderDetailLineBinding.inflate(layoutInflater, this, false)

            itemBinding.tvItemName.text = getString(
                R.string.customer_order_detail_item_name,
                item.quantity,
                item.name,
            )
            itemBinding.tvItemDescription.text = item.description
            itemBinding.tvItemPrice.text = formatPrice(item.price)

            if (item.imageRes != null) {
                itemBinding.ivItemImage.setImageResource(item.imageRes)
                itemBinding.tvItemPlaceholder.isVisible = false
            } else {
                itemBinding.ivItemImage.setImageResource(0)
                itemBinding.tvItemPlaceholder.isVisible = true
            }

            addView(itemBinding.root)
        }
    }

    private fun bindBill(bill: CustomerBillUiModel) = with(binding) {
        tvSubtotalValue.text = formatPrice(bill.subtotal)
        tvDeliveryFeeValue.text = formatPrice(bill.deliveryFee)
        tvTaxesValue.text = formatPrice(bill.taxes)
        tvDiscountLabel.text = bill.discountLabel
        tvDiscountValue.text = formatSignedPrice(bill.discount)
        tvTotalAmount.text = formatPrice(bill.total)
    }

    private fun bindAddress(detail: CustomerOrderDetailUiModel) = with(binding) {
        tvDeliveredTo.text = detail.deliveryAddressTitle
        tvAddressLine1.text = detail.deliveryAddressLine1
        tvAddressLine2.text = detail.deliveryAddressLine2
    }

    private fun setupActions() = with(binding) {
        btnReorder.setOnClickListener {
            Toast.makeText(
                requireContext(),
                getString(R.string.customer_order_detail_reorder_toast),
                Toast.LENGTH_SHORT,
            ).show()
        }

        btnSupport.setOnClickListener {
            Toast.makeText(
                requireContext(),
                getString(R.string.customer_order_detail_support_toast),
                Toast.LENGTH_SHORT,
            ).show()
        }
    }

    private fun formatPrice(value: Double): String {
        return String.format(Locale.US, "$%.2f", value)
    }

    private fun formatSignedPrice(value: Double): String {
        return if (value < 0) {
            String.format(Locale.US, "-$%.2f", kotlin.math.abs(value))
        } else {
            String.format(Locale.US, "$%.2f", value)
        }
    }

    override fun onDestroyView() {
        _binding = null
        super.onDestroyView()
    }

    companion object {
        private const val ARG_ORDER_ID = "arg_order_id"
        private const val DEFAULT_ORDER_ID = "PT-9821"

        fun newInstance(orderId: String): CustomerOrderDetailFragment {
            return CustomerOrderDetailFragment().apply {
                arguments = Bundle().apply {
                    putString(ARG_ORDER_ID, orderId)
                }
            }
        }
    }
}

package com.devpro.pizzatime.feature.customer.orderhistory

import com.devpro.pizzatime.R
import com.devpro.pizzatime.feature.customer.orderdetail.CustomerBillUiModel
import com.devpro.pizzatime.feature.customer.orderdetail.CustomerOrderDetailUiModel
import com.devpro.pizzatime.feature.customer.orderdetail.CustomerOrderItemUiModel
import com.google.firebase.Timestamp
import com.google.firebase.firestore.DocumentSnapshot
import com.google.firebase.firestore.FirebaseFirestore
import java.text.SimpleDateFormat
import java.util.Date
import java.util.Locale

object CustomerOrderFirestoreRepository {

    private val firestore = FirebaseFirestore.getInstance()

    fun loadOrderHistory(
        customerId: String,
        onResult: (Result<List<CustomerOrderHistoryItemUiModel>>) -> Unit,
    ) {
        firestore.collection("orders")
            .whereEqualTo("customerId", customerId)
            .get()
            .addOnSuccessListener { snapshot ->
                val orders = snapshot.documents
                    .sortedByDescending { it.getTimestamp("createdAt")?.seconds ?: 0L }
                    .mapNotNull { it.toHistoryItem() }
                onResult(Result.success(orders))
            }
            .addOnFailureListener { e -> onResult(Result.failure(e)) }
    }

    fun loadOrderDetail(
        orderId: String,
        onResult: (Result<CustomerOrderDetailUiModel>) -> Unit,
    ) {
        firestore.collection("orders").document(orderId)
            .get()
            .addOnSuccessListener { doc ->
                if (!doc.exists()) {
                    onResult(Result.failure(Exception("Order $orderId not found")))
                    return@addOnSuccessListener
                }
                onResult(Result.success(doc.toOrderDetail()))
            }
            .addOnFailureListener { e -> onResult(Result.failure(e)) }
    }

    private fun DocumentSnapshot.toHistoryItem(): CustomerOrderHistoryItemUiModel {
        val statusStr = getString("status") ?: "PENDING"
        val total = getDouble("total") ?: 0.0
        val createdAt = getTimestamp("createdAt")
        val rawItems = get("items") as? List<*>

        return CustomerOrderHistoryItemUiModel(
            orderId = id,
            orderedAt = createdAt?.toHistoryDateString() ?: "",
            status = mapHistoryStatus(statusStr),
            itemSummary = buildItemSummary(rawItems),
            total = total,
            imageRes = if (!rawItems.isNullOrEmpty()) R.drawable.img_pizza_time else null,
        )
    }

    private fun DocumentSnapshot.toOrderDetail(): CustomerOrderDetailUiModel {
        val statusStr = getString("status") ?: "PENDING"
        val total = getDouble("total") ?: 0.0
        val subtotal = getDouble("subtotal") ?: 0.0
        val deliveryFee = getDouble("deliveryFee") ?: 0.0
        val discount = getDouble("discount") ?: 0.0
        val createdAt = getTimestamp("createdAt")
        val rawItems = get("items") as? List<*>

        return CustomerOrderDetailUiModel(
            orderId = id,
            statusLabel = statusStr,
            orderTime = createdAt?.toDisplayTime() ?: "",
            heroImageRes = R.drawable.img_pizza_time,
            heroMessage = mapStatusMessage(statusStr),
            items = rawItems?.mapNotNull { it.toOrderItem() } ?: emptyList(),
            bill = CustomerBillUiModel(
                subtotal = subtotal,
                deliveryFee = deliveryFee,
                taxes = 0.0,
                discountLabel = if (discount > 0) "Discount" else "",
                discount = if (discount > 0) -discount else 0.0,
                total = total,
            ),
            deliveryAddressTitle = if (statusStr == "DELIVERED") "DELIVERED TO" else "DELIVERING TO",
            deliveryAddressLine1 = getString("deliveryAddress") ?: "",
            deliveryAddressLine2 = "",
        )
    }

    private fun Any?.toOrderItem(): CustomerOrderItemUiModel? {
        val map = this as? Map<*, *> ?: return null
        val name = map["name"] as? String ?: return null
        val quantity = (map["quantity"] as? Long)?.toInt() ?: 1
        val unitPrice = map["unitPrice"] as? Double ?: 0.0
        return CustomerOrderItemUiModel(
            quantity = quantity,
            name = name,
            description = "",
            price = unitPrice * quantity,
            imageRes = null,
        )
    }

    private fun mapHistoryStatus(statusStr: String): CustomerOrderHistoryStatus {
        return when (statusStr.uppercase(Locale.US)) {
            "DELIVERED" -> CustomerOrderHistoryStatus.DELIVERED
            "CANCELLED", "CANCELED" -> CustomerOrderHistoryStatus.CANCELED
            else -> CustomerOrderHistoryStatus.IN_PROGRESS
        }
    }

    private fun mapStatusMessage(statusStr: String): String {
        return when (statusStr.uppercase(Locale.US)) {
            "DELIVERED" -> "Arrived safely"
            "DELIVERING" -> "On the way to you"
            "READY" -> "Ready for pickup"
            "BAKING" -> "In the oven"
            "PREPARING" -> "Being prepared"
            "CONFIRMED" -> "Order confirmed"
            "CANCELLED" -> "Order cancelled"
            else -> "Order received"
        }
    }

    private fun buildItemSummary(rawItems: List<*>?): List<String> {
        if (rawItems.isNullOrEmpty()) return emptyList()
        return rawItems.mapNotNull { item ->
            val map = item as? Map<*, *> ?: return@mapNotNull null
            val name = map["name"] as? String ?: return@mapNotNull null
            val quantity = (map["quantity"] as? Long)?.toInt() ?: 1
            "${quantity}x $name"
        }
    }

    private fun Timestamp.toHistoryDateString(): String {
        return SimpleDateFormat("MMM dd, yyyy · hh:mm a", Locale.US).format(Date(seconds * 1000))
    }

    private fun Timestamp.toDisplayTime(): String {
        return SimpleDateFormat("MMM dd, hh:mm a", Locale.US).format(Date(seconds * 1000))
    }
}

package com.devpro.pizzatime.feature.customer.orderhistory

import android.os.Bundle
import android.view.LayoutInflater
import android.view.View
import android.view.ViewGroup
import android.widget.LinearLayout
import android.widget.Toast
import androidx.core.content.ContextCompat
import androidx.core.view.isVisible
import androidx.fragment.app.Fragment
import com.devpro.pizzatime.R
import com.devpro.pizzatime.databinding.FragmentCustomerOrderHistoryBinding
import com.devpro.pizzatime.databinding.ItemCustomerOrderHistoryCardBinding
import com.devpro.pizzatime.feature.customer.common.bottomnav.CustomerBottomNavTab
import com.devpro.pizzatime.feature.customer.common.bottomnav.setupCustomerBottomNav
import com.devpro.pizzatime.feature.customer.common.topbar.setupCustomerTopBar
import com.devpro.pizzatime.feature.staff.navigation.openCustomerOrderDetail
import java.util.Locale
import kotlin.math.roundToInt

class CustomerOrderHistoryFragment : Fragment() {

    private var _binding: FragmentCustomerOrderHistoryBinding? = null
    private val binding: FragmentCustomerOrderHistoryBinding
        get() = checkNotNull(_binding) {
            "FragmentCustomerOrderHistoryBinding is only valid between onCreateView and onDestroyView."
        }

    private val historyData: CustomerOrderHistoryUiModel = FakeCustomerOrderHistoryData.getOrderHistory()
    private var selectedFilter: CustomerOrderHistoryFilter = CustomerOrderHistoryFilter.ALL

    override fun onCreateView(
        inflater: LayoutInflater,
        container: ViewGroup?,
        savedInstanceState: Bundle?,
    ): View {
        _binding = FragmentCustomerOrderHistoryBinding.inflate(inflater, container, false)
        return binding.root
    }

    override fun onViewCreated(view: View, savedInstanceState: Bundle?) {
        bindStaticContent()
        setupFilterActions()
        setupTopBar()
        setupBottomNav()
        renderFilterChips()
        renderOrders()
        renderRewardCard()
    }

    private fun bindStaticContent() = with(binding) {
        tvTitle.text = historyData.title
        tvSubtitle.text = historyData.subtitle
    }

    private fun setupFilterActions() = with(binding) {
        chipAllOrders.setOnClickListener {
            selectedFilter = CustomerOrderHistoryFilter.ALL
            renderFilterChips()
            renderOrders()
        }

        chipDelivered.setOnClickListener {
            selectedFilter = CustomerOrderHistoryFilter.DELIVERED
            renderFilterChips()
            renderOrders()
        }

        chipCanceled.setOnClickListener {
            selectedFilter = CustomerOrderHistoryFilter.CANCELED
            renderFilterChips()
            renderOrders()
        }
    }

    private fun setupTopBar() = with(binding) {
        setupCustomerTopBar(
            topBar = customerTopBar,
            cartItemCount = 2,
            onCartClick = {
                Toast.makeText(
                    requireContext(),
                    getString(R.string.customer_promo_cart_toast),
                    Toast.LENGTH_SHORT,
                ).show()
            },
        )
    }
    private fun setupBottomNav() = with(binding) {
        setupCustomerBottomNav(
            bottomNav = customerBottomNav,
            selectedTab = CustomerBottomNavTab.ORDERS,
            onCustomerMenuClick = {
                // TODO: open pizza menu / customer home
            },
            onCustomerLoyaltyClick = {
                // TODO: open promo codes
            },
            onCustomerProfileClick = {
                // TODO: open customer profile
            },
        )
    }

    private fun renderFilterChips() = with(binding) {
        renderChip(chipAllOrders, selectedFilter == CustomerOrderHistoryFilter.ALL)
        renderChip(chipDelivered, selectedFilter == CustomerOrderHistoryFilter.DELIVERED)
        renderChip(chipCanceled, selectedFilter == CustomerOrderHistoryFilter.CANCELED)
    }

    private fun renderChip(view: View, selected: Boolean) {
        view.setBackgroundResource(
            if (selected) {
                R.drawable.bg_customer_order_history_chip_selected
            } else {
                R.drawable.bg_customer_order_history_chip_outline
            },
        )
    }

    private fun renderOrders() = with(binding.orderHistoryContainer) {
        removeAllViews()

        getFilteredOrders().forEach { order ->
            val itemBinding = ItemCustomerOrderHistoryCardBinding.inflate(layoutInflater, this, false)
            bindOrderCard(itemBinding, order)

            addView(
                itemBinding.root,
                LinearLayout.LayoutParams(
                    LinearLayout.LayoutParams.MATCH_PARENT,
                    LinearLayout.LayoutParams.WRAP_CONTENT,
                ).apply {
                    bottomMargin = 24.dp()
                },
            )
        }
    }

    private fun getFilteredOrders(): List<CustomerOrderHistoryItemUiModel> {
        return when (selectedFilter) {
            CustomerOrderHistoryFilter.ALL -> historyData.orders
            CustomerOrderHistoryFilter.DELIVERED -> historyData.orders.filter {
                it.status == CustomerOrderHistoryStatus.DELIVERED
            }
            CustomerOrderHistoryFilter.CANCELED -> historyData.orders.filter {
                it.status == CustomerOrderHistoryStatus.CANCELED
            }
        }
    }

    private fun bindOrderCard(
        itemBinding: ItemCustomerOrderHistoryCardBinding,
        order: CustomerOrderHistoryItemUiModel,
    ) = with(itemBinding) {
        tvOrderedAt.text = order.orderedAt
        tvOrderId.text = getString(R.string.customer_order_history_order_id, order.orderId)
        tvStatus.text = order.status.label
        tvTotal.text = formatPrice(order.total)
        tvItemSummary.text = order.itemSummary.joinToString(separator = "\n")

        if (order.imageRes != null) {
            ivOrderImage.setImageResource(order.imageRes)
            tvOrderImagePlaceholder.isVisible = false
        } else {
            ivOrderImage.setImageResource(0)
            tvOrderImagePlaceholder.isVisible = true
        }

        bindStatusStyle(itemBinding, order.status)
        bindOrderActions(itemBinding, order)
    }

    private fun bindStatusStyle(
        itemBinding: ItemCustomerOrderHistoryCardBinding,
        status: CustomerOrderHistoryStatus,
    ) = with(itemBinding) {
        when (status) {
            CustomerOrderHistoryStatus.DELIVERED -> {
                tvStatus.setBackgroundResource(R.drawable.bg_customer_order_history_status_delivered)
                tvStatus.setTextColor(ContextCompat.getColor(requireContext(), R.color.pt_basil_green))
            }
            CustomerOrderHistoryStatus.CANCELED -> {
                tvStatus.setBackgroundResource(R.drawable.bg_customer_order_history_status_canceled)
                tvStatus.setTextColor(ContextCompat.getColor(requireContext(), R.color.pt_copper))
            }
        }
    }

    private fun bindOrderActions(
        itemBinding: ItemCustomerOrderHistoryCardBinding,
        order: CustomerOrderHistoryItemUiModel,
    ) = with(itemBinding) {
        when (order.status) {
            CustomerOrderHistoryStatus.DELIVERED -> {
                btnSecondary.text = getString(R.string.customer_order_history_view_details)
                btnPrimary.text = getString(R.string.customer_order_history_reorder)
                btnPrimary.setBackgroundResource(R.drawable.bg_customer_order_history_primary_button)
                btnSecondary.setBackgroundResource(R.drawable.bg_customer_order_history_outline_button)

                btnSecondary.setOnClickListener {
                    openCustomerOrderDetail(order.orderId)
                }

                btnPrimary.setOnClickListener {
                    showComingSoonToast(R.string.customer_order_history_reorder_toast)
                }
            }

            CustomerOrderHistoryStatus.CANCELED -> {
                btnSecondary.text = getString(R.string.customer_order_history_support)
                btnPrimary.text = getString(R.string.customer_order_history_try_again)
                btnPrimary.setBackgroundResource(R.drawable.bg_customer_order_history_outline_button)
                btnSecondary.setBackgroundResource(R.drawable.bg_customer_order_history_muted_outline_button)

                btnSecondary.setOnClickListener {
                    showComingSoonToast(R.string.customer_order_history_support_toast)
                }

                btnPrimary.setOnClickListener {
                    showComingSoonToast(R.string.customer_order_history_try_again_toast)
                }
            }
        }
    }

    private fun renderRewardCard() = with(binding) {
        tvRewardTitle.text = historyData.reward.title
        tvRewardDescription.text = historyData.reward.description
        tvRewardCurrentOrders.text = getString(
            R.string.customer_order_history_orders_count,
            historyData.reward.currentOrders,
        )
        tvRewardTargetOrders.text = getString(
            R.string.customer_order_history_orders_count,
            historyData.reward.targetOrders,
        )

        rewardProgress.progress = historyData.reward.currentOrders
        rewardProgress.max = historyData.reward.targetOrders
    }

    private fun showComingSoonToast(messageRes: Int) {
        Toast.makeText(
            requireContext(),
            getString(messageRes),
            Toast.LENGTH_SHORT,
        ).show()
    }

    private fun formatPrice(value: Double): String {
        return String.format(Locale.US, "$%.2f", value)
    }

    private fun Int.dp(): Int {
        return (this * resources.displayMetrics.density).roundToInt()
    }

    override fun onDestroyView() {
        _binding = null
        super.onDestroyView()
    }
}

package com.devpro.pizzatime.feature.customer.orderhistory

import android.os.Bundle
import android.view.LayoutInflater
import android.view.View
import android.view.ViewGroup
import android.widget.LinearLayout
import android.widget.Toast
import androidx.core.content.ContextCompat
import androidx.core.view.isVisible
import androidx.fragment.app.Fragment
import com.devpro.pizzatime.R
import com.devpro.pizzatime.databinding.FragmentCustomerOrderHistoryBinding
import com.devpro.pizzatime.databinding.ItemCustomerOrderHistoryCardBinding
import com.devpro.pizzatime.feature.customer.common.bottomnav.CustomerBottomNavTab
import com.devpro.pizzatime.feature.customer.common.bottomnav.setupCustomerBottomNav
import com.devpro.pizzatime.feature.customer.common.topbar.setupCustomerTopBar
import com.devpro.pizzatime.feature.staff.navigation.openCustomerOrderDetail
import com.google.firebase.auth.FirebaseAuth
import java.util.Locale
import kotlin.math.roundToInt

class CustomerOrderHistoryFragment : Fragment() {

    private var _binding: FragmentCustomerOrderHistoryBinding? = null
    private val binding: FragmentCustomerOrderHistoryBinding
        get() = checkNotNull(_binding) {
            "FragmentCustomerOrderHistoryBinding is only valid between onCreateView and onDestroyView."
        }

    private val historyData: CustomerOrderHistoryUiModel = FakeCustomerOrderHistoryData.getOrderHistory()
    private var selectedFilter: CustomerOrderHistoryFilter = CustomerOrderHistoryFilter.ALL
    private var firestoreOrders: List<CustomerOrderHistoryItemUiModel>? = null

    override fun onCreateView(
        inflater: LayoutInflater,
        container: ViewGroup?,
        savedInstanceState: Bundle?,
    ): View {
        _binding = FragmentCustomerOrderHistoryBinding.inflate(inflater, container, false)
        return binding.root
    }

    override fun onViewCreated(view: View, savedInstanceState: Bundle?) {
        bindStaticContent()
        setupFilterActions()
        setupTopBar()
        setupBottomNav()
        renderFilterChips()
        renderOrders()
        renderRewardCard()
        loadFirestoreOrders()
    }

    private fun bindStaticContent() = with(binding) {
        tvTitle.text = historyData.title
        tvSubtitle.text = historyData.subtitle
    }

    private fun setupFilterActions() = with(binding) {
        chipAllOrders.setOnClickListener {
            selectedFilter = CustomerOrderHistoryFilter.ALL
            renderFilterChips()
            renderOrders()
        }

        chipDelivered.setOnClickListener {
            selectedFilter = CustomerOrderHistoryFilter.DELIVERED
            renderFilterChips()
            renderOrders()
        }

        chipCanceled.setOnClickListener {
            selectedFilter = CustomerOrderHistoryFilter.CANCELED
            renderFilterChips()
            renderOrders()
        }
    }

    private fun setupTopBar() = with(binding) {
        setupCustomerTopBar(
            topBar = customerTopBar,
            cartItemCount = 2,
            onCartClick = {
                Toast.makeText(
                    requireContext(),
                    getString(R.string.customer_promo_cart_toast),
                    Toast.LENGTH_SHORT,
                ).show()
            },
        )
    }

    private fun setupBottomNav() = with(binding) {
        setupCustomerBottomNav(
            bottomNav = customerBottomNav,
            selectedTab = CustomerBottomNavTab.ORDERS,
            onCustomerMenuClick = {},
            onCustomerLoyaltyClick = {},
            onCustomerProfileClick = {},
        )
    }

    private fun renderFilterChips() = with(binding) {
        renderChip(chipAllOrders, selectedFilter == CustomerOrderHistoryFilter.ALL)
        renderChip(chipDelivered, selectedFilter == CustomerOrderHistoryFilter.DELIVERED)
        renderChip(chipCanceled, selectedFilter == CustomerOrderHistoryFilter.CANCELED)
    }

    private fun renderChip(view: View, selected: Boolean) {
        view.setBackgroundResource(
            if (selected) {
                R.drawable.bg_customer_order_history_chip_selected
            } else {
                R.drawable.bg_customer_order_history_chip_outline
            },
        )
    }

    private fun renderOrders() = with(binding.orderHistoryContainer) {
        removeAllViews()

        getFilteredOrders().forEach { order ->
            val itemBinding = ItemCustomerOrderHistoryCardBinding.inflate(layoutInflater, this, false)
            bindOrderCard(itemBinding, order)

            addView(
                itemBinding.root,
                LinearLayout.LayoutParams(
                    LinearLayout.LayoutParams.MATCH_PARENT,
                    LinearLayout.LayoutParams.WRAP_CONTENT,
                ).apply {
                    bottomMargin = 24.dp()
                },
            )
        }
    }

    private fun getFilteredOrders(): List<CustomerOrderHistoryItemUiModel> {
        val orders = firestoreOrders ?: historyData.orders
        return when (selectedFilter) {
            CustomerOrderHistoryFilter.ALL -> orders
            CustomerOrderHistoryFilter.DELIVERED -> orders.filter {
                it.status == CustomerOrderHistoryStatus.DELIVERED
            }
            CustomerOrderHistoryFilter.CANCELED -> orders.filter {
                it.status == CustomerOrderHistoryStatus.CANCELED
            }
        }
    }

    private fun bindOrderCard(
        itemBinding: ItemCustomerOrderHistoryCardBinding,
        order: CustomerOrderHistoryItemUiModel,
    ) = with(itemBinding) {
        tvOrderedAt.text = order.orderedAt
        tvOrderId.text = getString(R.string.customer_order_history_order_id, order.orderId)
        tvStatus.text = order.status.label
        tvTotal.text = formatPrice(order.total)
        tvItemSummary.text = order.itemSummary.joinToString(separator = "\n")

        if (order.imageRes != null) {
            ivOrderImage.setImageResource(order.imageRes)
            tvOrderImagePlaceholder.isVisible = false
        } else {
            ivOrderImage.setImageResource(0)
            tvOrderImagePlaceholder.isVisible = true
        }

        bindStatusStyle(itemBinding, order.status)
        bindOrderActions(itemBinding, order)
    }

    private fun bindStatusStyle(
        itemBinding: ItemCustomerOrderHistoryCardBinding,
        status: CustomerOrderHistoryStatus,
    ) = with(itemBinding) {
        when (status) {
            CustomerOrderHistoryStatus.DELIVERED -> {
                tvStatus.setBackgroundResource(R.drawable.bg_customer_order_history_status_delivered)
                tvStatus.setTextColor(ContextCompat.getColor(requireContext(), R.color.pt_basil_green))
            }
            CustomerOrderHistoryStatus.CANCELED -> {
                tvStatus.setBackgroundResource(R.drawable.bg_customer_order_history_status_canceled)
                tvStatus.setTextColor(ContextCompat.getColor(requireContext(), R.color.pt_copper))
            }
            CustomerOrderHistoryStatus.IN_PROGRESS -> {
                tvStatus.setBackgroundResource(R.drawable.bg_customer_order_history_status_delivered)
                tvStatus.setTextColor(ContextCompat.getColor(requireContext(), R.color.pt_basil_green))
            }
        }
    }

    private fun bindOrderActions(
        itemBinding: ItemCustomerOrderHistoryCardBinding,
        order: CustomerOrderHistoryItemUiModel,
    ) = with(itemBinding) {
        when (order.status) {
            CustomerOrderHistoryStatus.DELIVERED -> {
                btnSecondary.text = getString(R.string.customer_order_history_view_details)
                btnPrimary.text = getString(R.string.customer_order_history_reorder)
                btnPrimary.setBackgroundResource(R.drawable.bg_customer_order_history_primary_button)
                btnSecondary.setBackgroundResource(R.drawable.bg_customer_order_history_outline_button)

                btnSecondary.setOnClickListener { openCustomerOrderDetail(order.orderId) }
                btnPrimary.setOnClickListener { showComingSoonToast(R.string.customer_order_history_reorder_toast) }
            }

            CustomerOrderHistoryStatus.CANCELED -> {
                btnSecondary.text = getString(R.string.customer_order_history_support)
                btnPrimary.text = getString(R.string.customer_order_history_try_again)
                btnPrimary.setBackgroundResource(R.drawable.bg_customer_order_history_outline_button)
                btnSecondary.setBackgroundResource(R.drawable.bg_customer_order_history_muted_outline_button)

                btnSecondary.setOnClickListener { showComingSoonToast(R.string.customer_order_history_support_toast) }
                btnPrimary.setOnClickListener { showComingSoonToast(R.string.customer_order_history_try_again_toast) }
            }

            CustomerOrderHistoryStatus.IN_PROGRESS -> {
                btnSecondary.text = getString(R.string.customer_order_history_view_details)
                btnPrimary.text = getString(R.string.customer_order_history_view_details)
                btnPrimary.setBackgroundResource(R.drawable.bg_customer_order_history_primary_button)
                btnSecondary.setBackgroundResource(R.drawable.bg_customer_order_history_outline_button)

                btnSecondary.setOnClickListener { openCustomerOrderDetail(order.orderId) }
                btnPrimary.setOnClickListener { openCustomerOrderDetail(order.orderId) }
            }
        }
    }

    private fun renderRewardCard() = with(binding) {
        tvRewardTitle.text = historyData.reward.title
        tvRewardDescription.text = historyData.reward.description
        tvRewardCurrentOrders.text = getString(
            R.string.customer_order_history_orders_count,
            historyData.reward.currentOrders,
        )
        tvRewardTargetOrders.text = getString(
            R.string.customer_order_history_orders_count,
            historyData.reward.targetOrders,
        )

        rewardProgress.progress = historyData.reward.currentOrders
        rewardProgress.max = historyData.reward.targetOrders
    }

    private fun loadFirestoreOrders() {
        val uid = FirebaseAuth.getInstance().currentUser?.uid ?: return
        CustomerOrderFirestoreRepository.loadOrderHistory(uid) { result ->
            if (!isAdded) return@loadOrderHistory
            result.onSuccess { orders ->
                firestoreOrders = orders
                renderOrders()
            }
        }
    }

    private fun showComingSoonToast(messageRes: Int) {
        Toast.makeText(requireContext(), getString(messageRes), Toast.LENGTH_SHORT).show()
    }

    private fun formatPrice(value: Double): String {
        return String.format(Locale.US, "$%.2f", value)
    }

    private fun Int.dp(): Int {
        return (this * resources.displayMetrics.density).roundToInt()
    }

    override fun onDestroyView() {
        _binding = null
        super.onDestroyView()
    }
}

package com.devpro.pizzatime.feature.customer.orderhistory
data class CustomerOrderHistoryUiModel( val title: String, val subtitle: String, val orders: List<CustomerOrderHistoryItemUiModel>, val reward: CustomerOrderRewardUiModel, )
data class CustomerOrderHistoryItemUiModel( val orderId: String, val orderedAt: String, val status: CustomerOrderHistoryStatus, val itemSummary: List<String>, val total: Double, val imageRes: Int?, )
data class CustomerOrderRewardUiModel( val title: String, val description: String, val currentOrders: Int, val targetOrders: Int, )
enum class CustomerOrderHistoryStatus( val label: String, ) { DELIVERED("DELIVERED"), CANCELED("CANCELED"), }
enum class CustomerOrderHistoryFilter { ALL, DELIVERED, CANCELED, }

package com.devpro.pizzatime.feature.customer.orderhistory
data class CustomerOrderHistoryUiModel( val title: String, val subtitle: String, val orders: List<CustomerOrderHistoryItemUiModel>, val reward: CustomerOrderRewardUiModel, )
data class CustomerOrderHistoryItemUiModel( val orderId: String, val orderedAt: String, val status: CustomerOrderHistoryStatus, val itemSummary: List<String>, val total: Double, val imageRes: Int?, )
data class CustomerOrderRewardUiModel( val title: String, val description: String, val currentOrders: Int, val targetOrders: Int, )
enum class CustomerOrderHistoryStatus( val label: String, ) { DELIVERED("DELIVERED"), CANCELED("CANCELED"), IN_PROGRESS("IN PROGRESS"), }
enum class CustomerOrderHistoryFilter { ALL, DELIVERED, CANCELED, }
